    title.classList.add('vwo-lang-section');
    title.querySelector('p').textContent = 'Preferred Language';
    var block = eduBlock.cloneNode(true);
    block.classList.add('vwo-lang-section', 'vwo-lang-options');
    var row = block.firstElementChild, tmpl = row.firstElementChild;
